```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

const lines = [];
rl.on('line', line => {
    lines.push(line);
});

rl.on('close', () => {
    const firstLine = lines[0].split(' ').map(Number);
    const [n, m, c0, d0] = firstLine;

    const stuffings = [];
    for (let i = 1; i <= m; i++) {
        const parts = lines[i].split(' ').map(Number);
        const [ai, bi, ci, di] = parts;
        stuffings.push({ ai, bi, ci, di });
    }

    // dp[dough_used] = max money
    // But we need to track dough used, and for each stuffing type, how many buns we can make is limited by ai/bi
    // Let's use a 2D DP: dp[i][j] = max money using first i stuffing types and j grams of dough
    // i from 0 to m, j from 0 to n

    const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));

    // Initialize: for 0 stuffing types, we can only make plain buns
    // Actually, let's think differently. We process each stuffing type one by one.
    // For each stuffing type i, we can make k buns where 0 <= k <= floor(ai/bi) and k*ci <= remaining dough
    // But we also have the option to make plain buns at the end.

    // Let's do: dp[i][j] = max money using first i stuffing types and exactly j grams of dough
    // Then at the end, for each j, we can add plain buns with (n-j) dough: floor((n-j)/c0) * d0

    // Initialize dp[0][j] = 0 for all j (no stuffings used, no money from stuffings)
    // Actually dp[0][j] should be 0 because we haven't used any dough for stuffings yet.
    // But we need to be careful: dp[i][j] means we've used exactly j dough for the first i stuffing types.

    for (let i = 0; i <= m; i++) {
        for (let j = 0; j <= n; j++) {
            dp[i][j] = 0;
        }
    }

    for (let i = 1; i <= m; i++) {
        const { ai, bi, ci, di } = stuffings[i - 1];
        const maxBuns = Math.floor(ai / bi);

        for (let j = 0; j <= n; j++) {
            // Option 1: don't use any of this stuffing type
            dp[i][j] = dp[i - 1][j];

            // Option 2: use k buns of this stuffing type
            for (let k = 1; k <= maxBuns; k++) {
                const doughNeeded = k * ci;
                if (doughNeeded > j) break;
                const money = k * di;
                dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - doughNeeded] + money);
            }
        }
    }

    let maxMoney = 0;
    for (let j = 0; j <= n; j++) {
        const remainingDough = n - j;
        const plainBuns = Math.floor(remainingDough / c0);
        const totalMoney = dp[m][j] + plainBuns * d0;
        maxMoney = Math.max(maxMoney, totalMoney);
    }

    console.log(maxMoney);
});
