    // We can do a simple unbounded knapsack update

    const finalDp = new Array(n + 1).fill(0);
    for (let j = 0; j <= n; j++) {
        finalDp[j] = dp[j];
    }

    // For plain buns, we can make any number up to floor(n/c0)
    // Unbounded knapsack: iterate j from c0 to n
    for (let j = c0; j <= n; j++) {
        if (finalDp[j - c0] + d0 > finalDp[j]) {
            finalDp[j] = finalDp[j - c0] + d0;
