    // Let's create an array of all items including plain buns.
    const items = [];
    for (const s of stuffings) {
        items.push({ a: s.ai, b: s.bi, c: s.ci, d: s.di });
    }
    // Add plain buns: no stuffing limit
    items.push({ a: Infinity, b: 0, c: c0, d: d0 });

    // Now do bounded knapsack
    // dp[d] = max earnings with d grams of dough used
    const dp = new Array(n + 1).fill(0);

    for (const item of items) {
        const { a, b, c, d } = item;
        // Max number of buns we can make with this item
        let maxK;
        if (b === 0) {
            maxK = Math.floor(n / c);
        } else {
            maxK = Math.min(Math.floor(a / b), Math.floor(n / c));
        }

        // For each amount of dough from n down to 0
        for (let dough = n; dough >= 0; dough--) {
            // Try making k buns of this type
            for (let k = 1; k <= maxK; k++) {
                if (k * c > dough) break;
                const prevDough = dough - k * c;
                const newEarnings = dp[prevDough] + k * d;
                if (newEarnings > dp[dough]) {
                    dp[dough] = newEarnings;
                }
            }
        }
    }

    // The answer is the max value in dp
    let ans = 0;
    for (let i = 0; i <= n; i++) {
        if (dp[i] > ans) ans = dp[i];
    }

    console.log(ans);
});
